<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое бюджетные инвестиции юридическому лицу?", "acceptedAnswer": {"@type": "Answer", "text": "Это бюджетные средства, при предоставлении которых у государства или муниципалитета возникает право собственности на эквивалентную долю в уставном (складочном) капитале получателя. Регулируются статьёй 80 Бюджетного кодекса."}}, {"@type": "Question", "name": "Чем бюджетные инвестиции отличаются от субсидии?", "acceptedAnswer": {"@type": "Answer", "text": "При субсидии государство не получает долю в капитале, а при бюджетной инвестиции — получает. Субсидия по общему правилу безвозмездна и безвозвратна, инвестиция — это вложение в капитал с возникновением имущественного права у бюджета."}}, {"@type": "Question", "name": "Кто может получить бюджетные инвестиции по статье 80?", "acceptedAnswer": {"@type": "Answer", "text": "Юридические лица, не являющиеся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями, — как правило, хозяйственные общества, в капитале которых может участвовать государство."}}, {"@type": "Question", "name": "Как оформляются бюджетные инвестиции?", "acceptedAnswer": {"@type": "Answer", "text": "Договором об участии публично-правового образования в собственности получателя. Договор заключается в течение трёх месяцев после вступления в силу закона (решения) о бюджете; без договора инвестиции не предоставляются."}}, {"@type": "Question", "name": "Подлежат ли бюджетные инвестиции казначейскому сопровождению?", "acceptedAnswer": {"@type": "Answer", "text": "Да, по общему правилу. Бюджетные инвестиции относятся к целевым средствам и в перечне на 2026 год названы среди средств, сопровождаемых без порога. Отдельные случаи и исключения определяются актами Правительства."}}, {"@type": "Question", "name": "Что будет, если не заключить договор в срок?", "acceptedAnswer": {"@type": "Answer", "text": "Отсутствие заключённых в установленный срок договоров об участии является основанием для непредоставления бюджетных инвестиций."}}, {"@type": "Question", "name": "Какие корпоративные последствия у бюджетных инвестиций?", "acceptedAnswer": {"@type": "Answer", "text": "Возникает доля или акции публично-правового образования в уставном капитале, что влечёт изменения в составе участников и учредительных документах, оформляемые по корпоративному законодательству."}}, {"@type": "Question", "name": "Нужно ли вести обособленный учёт инвестиций?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Как целевые средства, бюджетные инвестиции учитываются обособленно, расходы подтверждаются документами и проходят проверку целевого характера, а по итогам формируется отчётность об использовании."}}]}
</script>
